function withSoundAssetVersion(url) {
  const raw = String(url || "").trim();
  if (!raw) return raw;
  const joiner = raw.includes("?") ? "&" : "?";
  return `${raw}${joiner}v=${encodeURIComponent(SOUND_ASSET_VERSION)}`;
}

