function generateInstallId() {
  try {
    if (typeof crypto !== "undefined" && crypto.randomUUID) {
      return crypto.randomUUID();
    }
  } catch (_) {}
  return `iid-${Date.now()}-${Math.floor(Math.random() * 1e6)}`;
}

function normalizeInstallIdForLink(raw) {
  if (typeof raw !== "string") return "";
  const trimmed = raw.trim();
  if (!trimmed || trimmed.length > MAX_INSTALL_ID_LEN) return "";
  return trimmed;
}

function computeLinkCodeChecksum(raw) {
  const input = String(raw || "");
  let h = 2166136261;
  for (let i = 0; i < input.length; i += 1) {
    h ^= input.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(36).padStart(6, "0").slice(-6);
}

function encodeBase64Url(raw) {
  const source = String(raw || "");
  try {
    if (typeof btoa === "function") {
      return btoa(source).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
    }
  } catch (_) {}
  return "";
}

function decodeBase64Url(raw) {
  const input = String(raw || "").replace(/-/g, "+").replace(/_/g, "/");
  if (!input) return "";
  const padded = input + "=".repeat((4 - (input.length % 4)) % 4);
  try {
    if (typeof atob === "function") {
      return atob(padded);
    }
  } catch (_) {}
  return "";
}

function buildAccountLinkCode(installId) {
  const safeInstallId = normalizeInstallIdForLink(installId);
  if (!safeInstallId) return "";
  const payload = encodeBase64Url(safeInstallId);
  if (!payload) return "";
  const checksum = computeLinkCodeChecksum(payload);
  return `${ACCOUNT_LINK_CODE_PREFIX}-${payload}-${checksum}`;
}

function parseAccountLinkCode(rawCode) {
  const raw = String(rawCode || "").trim();
  if (!raw) return { ok: false, error: "empty" };
  const compact = raw.replace(/[‐‑‒–—﹘﹣－]/g, "-").replace(/\s+/g, "");
  const match = compact.match(/^([A-Za-z0-9]+)-([A-Za-z0-9_-]+)-([A-Za-z0-9]+)$/);
  if (!match) return { ok: false, error: "format" };
  const prefix = String(match[1] || "").toUpperCase();
  if (prefix !== ACCOUNT_LINK_CODE_PREFIX) return { ok: false, error: "prefix" };
  const payload = String(match[2] || "");
  const checksum = String(match[3] || "").toLowerCase();
  const expected = computeLinkCodeChecksum(payload);
  if (checksum !== expected) return { ok: false, error: "checksum" };
  const decodedInstallId = normalizeInstallIdForLink(decodeBase64Url(payload));
  if (!decodedInstallId) return { ok: false, error: "install_id" };
  return { ok: true, installId: decodedInstallId };
}

function getOrCreateInstallId() {
  try {
    const existing = localStorage.getItem(INSTALL_ID_STORAGE_KEY);
    if (existing && existing.trim()) return existing.trim();
    const legacy = localStorage.getItem("boggle_client_id");
    if (legacy && legacy.trim()) {
      localStorage.setItem(INSTALL_ID_STORAGE_KEY, legacy.trim());
      return legacy.trim();
    }
    const fresh = generateInstallId();
    localStorage.setItem(INSTALL_ID_STORAGE_KEY, fresh);
    localStorage.setItem(INSTALL_ID_CREATED_AT_STORAGE_KEY, String(Date.now()));
    return fresh;
  } catch (_) {
    return generateInstallId();
  }
}

function getInstallIdCreatedAtTs() {
  try {
    const raw = localStorage.getItem(INSTALL_ID_CREATED_AT_STORAGE_KEY);
    const ts = Number(raw);
    return Number.isFinite(ts) && ts > 0 ? ts : null;
  } catch (_) {
    return null;
  }
}

function getPatchNotesSeenStorageKey(installId, version = PATCH_NOTES_VERSION) {
  const safeInstallId = typeof installId === "string" ? installId.trim() : "";
  if (!safeInstallId) return "";
  return `${PATCH_NOTES_SEEN_STORAGE_PREFIX}:${version}:${safeInstallId}`;
}

function isInstallEligibleForPatchNotes(installId, installIdCreatedAtTs) {
  const safeInstallId = typeof installId === "string" ? installId.trim() : "";
  if (!safeInstallId) return false;
  if (!Number.isFinite(PATCH_NOTES_RELEASE_TS)) return true;
  if (!Number.isFinite(installIdCreatedAtTs)) {
    // Legacy installs without timestamp are considered existing installs.
    return true;
  }
  return installIdCreatedAtTs < PATCH_NOTES_RELEASE_TS;
}

function getChatMessageSortTime(message) {
  const tsCandidate =
    message?.t ??
    message?.ts ??
    message?.timestamp ??
    message?.createdAt ??
    0;
  const ts = Number(tsCandidate);
  return Number.isFinite(ts) ? ts : 0;
}

function dedupeChatMessages(messages) {
  const seen = new Set();
  const out = [];
  for (const raw of Array.isArray(messages) ? messages : []) {
    if (!raw || typeof raw !== "object") continue;
    const id = typeof raw.id === "string" ? raw.id : "";
    const key = id
      ? `id:${id}`
      : `fallback:${getChatMessageSortTime(raw)}:${raw.nick || raw.author || ""}:${raw.text || ""}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(raw);
  }
  return out;
}

function capChatMessagesByType(messages) {
  const deduped = dedupeChatMessages(messages);
  const system = [];
  const user = [];
  for (let i = deduped.length - 1; i >= 0; i -= 1) {
    const msg = deduped[i];
    if (isSystemChatMessage(msg)) {
      if (system.length < CHAT_SYSTEM_HISTORY_MAX) {
        system.push(msg);
      }
      continue;
    }
    if (user.length < CHAT_MESSAGES_HISTORY_MAX) {
      user.push(msg);
    }
  }
  const merged = [...user.reverse(), ...system.reverse()];
  merged.sort((a, b) => {
    const tA = getChatMessageSortTime(a);
    const tB = getChatMessageSortTime(b);
    if (tA !== tB) return tA - tB;
    return String(a?.id || "").localeCompare(String(b?.id || ""));
  });
  return merged.slice(-CHAT_BUFFER_MAX);
}

function readStoredChatMessages() {
  if (typeof window === "undefined" || typeof localStorage === "undefined") {
    return [];
  }
  try {
    const raw = localStorage.getItem(CHAT_MESSAGES_STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return capChatMessagesByType(parsed);
  } catch (_) {
    return [];
  }
}

function getBroadcastMessageKey(message) {
  if (!message || typeof message !== "object") return "";
  const idPart = typeof message.id === "string" ? message.id.trim() : "";
  const updatedPart =
    typeof message.updatedAt === "string" ? message.updatedAt.trim() : "";
  if (idPart && updatedPart) return `${idPart}:${updatedPart}`.slice(0, 140);
  if (idPart) return idPart.slice(0, 140);
  if (updatedPart) return updatedPart.slice(0, 140);
  return "";
}

function getBroadcastSeenStorageKey(installId, messageKey) {
  const safeInstallId = typeof installId === "string" ? installId.trim() : "";
  const safeMessageKey = typeof messageKey === "string" ? messageKey.trim() : "";
  if (!safeInstallId || !safeMessageKey) return "";
  return `${BROADCAST_SEEN_STORAGE_PREFIX}:${safeInstallId}:${safeMessageKey}`;
}

