      clearQueuedRankingUpdate();
      stopImplodePhase();
      pendingBreakStartRef.current = null;
      pendingRoundEndRef.current = null;
      outroInFlightRef.current = false;
      outroRoundRef.current = null;
      setInputLocked(false);
