      setFinalResults([]);
      setResultsTeamDelta({ red: 0, blue: 0 });
      setProvisionalRanking([]);
      setAnnouncements([]);
      setNextStartAt(null);
      setUpcomingSpecial(nextSpecial && nextSpecial.isSpecial ? nextSpecial : null);
      setBreakKind(null);
      setTournamentSummary(null);
