    const dateId = duelStatus?.objectives?.dateId || duelStatus?.dateId || "";
    if (dateId) {
      setDuelObjectivesPopupDismissedDateId(dateId);
    }
    setDuelPopupState({ mode: null, step: 0, team: null, weekId: null });
